ont-size:13px;font-weight:700}.search-empty{max-width:620px;margin:auto;padding:38px;border:1px solid var(--border);border-radius:24px;background:var(--muted);color:var(--muted-foreground);text-align:center}@media(max-width:620px){.ts-hero{padding:44px 0 48px}.search-content{padding:36px 0 64px}.result-card{grid-template-columns:1fr}.result-side{text-align:left}.result-open{margin-top:8px}}
